function numberOfGoodPartitions(nums) {
  const MOD = 1_000_000_007;
  const lastIndex = new Map();
  for (let i = 0; i < nums.length; i++) {
    lastIndex.set(nums[i], i);
  }
  let answer = 1;
  let reach = 0;
  for (let i = 0; i < nums.length; i++) {
    if (i > reach) {
      answer = (answer * 2) % MOD;
    }
    reach = Math.max(reach, lastIndex.get(nums[i]));
  }
  return answer;
}

