function numberOfGoodPartitions(nums) {
  const n = nums.length;
  let count = 0;
  // Bit k of mask set means a cut between positions k and k + 1.
  for (let mask = 0; mask < 1 << (n - 1); mask++) {
    const pieceOf = new Map();
    let piece = 0;
    let good = true;
    for (let k = 0; k < n && good; k++) {
      if (pieceOf.has(nums[k]) && pieceOf.get(nums[k]) !== piece) good = false;
      pieceOf.set(nums[k], piece);
      if ((mask >> k) & 1) piece++;
    }
    if (good) count++;
  }
  return count % 1000000007;
}

