function generate(rand, size) {
  const pick = top => 1 + Math.floor(rand() * top);
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 10);
    const top = [1, 3, 6, 12, 1000000000][Math.floor(rand() * 5)];
    return [Array.from({ length: n }, () => pick(top))];
  }
  const n = 2000;
  const mode = Math.floor(rand() * 3);
  if (mode === 0) {
    const used = new Set();
    while (used.size < n) used.add(pick(1000000000));
    return [[...used]];
  }
  if (mode === 1) return [Array.from({ length: n }, () => pick(1500))];
  // Short blocks that reuse their own values, so many minimal segments appear.
  const nums = [];
  let base = 0;
  while (nums.length < n) {
    const width = 1 + Math.floor(rand() * 3);
    const length = Math.min(n - nums.length, width + Math.floor(rand() * 4));
    for (let k = 0; k < length; k++) nums.push(base + 1 + Math.floor(rand() * width));
    base += width;
  }
  return [nums];
}
